import{_ as i,o,c as s,ai as t}from"./chunks/framework.DnX3IzGy.js";const r="/images/discord_full-server-menu-roles.png",a="/images/discord_full-linkedroles-select.png",n="/images/discord_full-linkedroles-claim.png",f=JSON.parse('{"title":"Linked Roles","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/discord/linked-roles.md","filePath":"user-guide/discord/linked-roles.md"}'),l={name:"user-guide/discord/linked-roles.md"};function c(d,e,u,p,m,h){return o(),s("div",null,e[0]||(e[0]=[t('<h1 id="linked-roles" tabindex="-1">Linked Roles <a class="header-anchor" href="#linked-roles" aria-label="Permalink to &quot;Linked Roles&quot;">​</a></h1><p>Citizen iD supports Discord’s <a href="https://support.discord.com/hc/en-us/articles/10388356626711-Connections-Linked-Roles-Admins" target="_blank">Linked Roles</a> feature, allowing users to easily claim application-linked roles on any server. Individual roles may have requirements based on your RSI account verification status, RSI account age and other linked data. This integration removes the need for manual role management and ensures access is always in sync with your verification status.</p><p>To claim a linked role, start by navigating to the server’s menu in Discord and selecting <strong>Linked Roles</strong>. <img src="'+r+'" alt="Discord server menu"></p><p>You’ll see a list of available Linked Roles, along with the application icons. Select the appropriate role which has the Citizen iD application icon to begin the connection process. <img src="'+a+'" alt="Discord linked roles selection"></p><p>Discord may display a prompt to connect your Citizen iD account. This step verifies that your account meets the role requirements—for example, having a verified RSI profile that is at least a certain number of days old. Once verified, click <strong>Finish</strong> to complete the process. <img src="'+n+'" alt="Discord linked roles claim screen"></p><p>When the link is successful, the corresponding role will be immediately to your Discord account for that server.</p><h2 id="role-removal" tabindex="-1">Role Removal <a class="header-anchor" href="#role-removal" aria-label="Permalink to &quot;Role Removal&quot;">​</a></h2><p>You can remove a linked role manually by following a similar &quot;unclaim&quot; process within the <strong>Linked Roles</strong> menu, or by deauthorizing the Citizen iD application from your <strong>Authorized Apps</strong> in Discord settings.</p><p>Additionally, roles may be removed automatically if your account status changes and no longer meets the requirements defined by the server administrators.</p><hr><p><em>Last updated: August 2025</em></p>',11)]))}const _=i(l,[["render",c]]);export{f as __pageData,_ as default};
